package com.onecall.archtests.container;

import static org.assertj.core.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.*;

public class OperationsCatalogDraftLifecycleIT {
    static final OperationsCatalogDraftFixture fixture = new OperationsCatalogDraftFixture();
    @BeforeAll static void start() throws Exception { fixture.start(); }
    @AfterAll static void stop() { fixture.close(); }
    @BeforeEach void reset() throws Exception { fixture.reset(); }
    @AfterEach void clean() throws Exception { fixture.clean(); }
    @Test void postgres16RunsExactlyV001ThroughV018() throws Exception { assertThat(fixture.value("SELECT version()")).contains("PostgreSQL 16."); assertThat(fixture.value("SELECT string_agg(version,',' ORDER BY installed_rank) FROM public.flyway_schema_history WHERE success AND version IS NOT NULL")).isEqualTo(java.util.stream.IntStream.rangeClosed(1, 19).mapToObj(number -> "%03d".formatted(number)).collect(java.util.stream.Collectors.joining(","))); fixture.provisioningOracle(); }
    @Test void createPersistsOneDraftAndExactCanonicalSnapshotHash() throws Exception { UUID product = fixture.product(); var response = fixture.create(product, 1, true); fixture.success(response, 201); fixture.exactStored(response);
        assertThat(fixture.value("SELECT before_snapshot IS NULL FROM audit.audit_fact")).isEqualTo("t");
        assertThat(fixture.value("SELECT a.after_snapshot = jsonb_build_object('productId',v.product_id,'versionNo',v.version_no,'saleStatus',v.sale_status,'revision',v.revision,'snapshotSha256',v.snapshot_sha256) FROM audit.audit_fact a JOIN catalog_order.catalog_version v ON a.object_id=v.id")).isEqualTo("t");
        assertThat(fixture.value("SELECT request_id='catalog_version:'||object_id||':draft:create' AND trace_id=? AND object_type='CATALOG_VERSION' FROM audit.audit_fact", fixture.callerTrace().toString())).isEqualTo("t");
        assertThat(fixture.value("SELECT count(*) FROM catalog_order.catalog_version")).isEqualTo("1"); assertThat(fixture.value("SELECT count(*) FROM catalog_order.catalog_benefit_line")).isEqualTo("2"); assertThat(fixture.value("SELECT count(*) FROM catalog_order.catalog_offer")).isEqualTo("2"); assertThat(fixture.base.audits()).isEqualTo(1); fixture.noPlatformWrites(); assertThat(fixture.value("SELECT actor_id FROM audit.audit_fact")).isEqualTo(fixture.base.shared.employee.toString()); assertThat(fixture.value("SELECT action_code||':'||actor_type||':'||reason_code FROM audit.audit_fact")).isEqualTo("CATALOG_DRAFT_CREATE:EMPLOYEE:ACTION_DERIVED"); }
    @Test void sameNaturalIdentityReplays200WithoutDuplicateRowsOrAudit() throws Exception { UUID product = fixture.product(); var created = fixture.create(product, 1, true); fixture.success(created, 201); String before = fixture.allFacts(); var replay = fixture.create(product, 1, true); fixture.success(replay, 200); assertThat(replay.body()).isEqualTo(created.body()); assertThat(fixture.allFacts()).isEqualTo(before); UUID version = UUID.fromString(fixture.mapper.readTree(created.body()).get("catalogVersionId").asString()); fixture.mutate("UPDATE catalog_order.catalog_version SET snapshot='{}'::jsonb WHERE id=?", version); before = fixture.allFacts(); fixture.problem(fixture.create(product, 1, true), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void changedNaturalProjectionConflictsWithoutWrites() throws Exception { UUID product = fixture.product(); var created = fixture.create(product, 1, true); fixture.success(created, 201); String before = fixture.allFacts(); fixture.problem(fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, 1, true).replace("\"priceCents\":0", "\"priceCents\":1"), "admin"), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.allFacts()).isEqualTo(before); UUID version = UUID.fromString(fixture.mapper.readTree(created.body()).get("catalogVersionId").asString()); fixture.mutate("UPDATE catalog_order.catalog_version SET snapshot_sha256=repeat('f',64) WHERE id=?", version); before = fixture.allFacts(); fixture.problem(fixture.create(product, 1, true), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void nonDraftNaturalIdentityConflictsEvenForEqualCommercialFields() throws Exception { UUID product = fixture.product(); UUID version = UUID.fromString(fixture.success(fixture.create(product, 1, false), 201).get("catalogVersionId").asString()); fixture.base.success(fixture.base.request(version, true, null, 1)); String before = fixture.allFacts(); fixture.problem(fixture.create(product, 1, false), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void missingProductAndVersionReturn404AfterAuthority() throws Exception { String before = fixture.allFacts(); fixture.problem(fixture.create(UUID.randomUUID(), 1, false), 404, "NOT_FOUND"); fixture.problem(fixture.replace(UUID.randomUUID(), 1, 0), 404, "NOT_FOUND"); assertThat(fixture.calls("FROM operations_iam.employee_account")).hasSize(2); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void allCommercialMatrixVariantsRoundTripExactly() throws Exception {
        UUID product = fixture.product(); int number = 1;
        for (String type : List.of("ONE_TIME", "ADD_ON", "SUBSCRIPTION", "QUOTE")) {
            String body = fixture.createBody(product, number++, true).replace("ONE_TIME", type);
            if (type.equals("SUBSCRIPTION")) body = body.replace("ONCE", "QUARTERLY").replace("\"installments\":1", "\"installments\":7").replace("\"grantIntervalMonths\":0,\"benefitLines\"", "\"grantIntervalMonths\":2,\"benefitLines\"");
            if (type.equals("QUOTE")) body = body.replace("PERSONAL", "ENTERPRISE").replace("ONCE", "QUOTE").replace("\"priceCents\":0", "\"priceCents\":null");
            var response = fixture.request("POST", OperationsCatalogDraftFixture.BASE, body, "admin"); fixture.success(response, 201); fixture.exactStored(response);
        }
        String before = fixture.allFacts(); fixture.problem(fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, 50, false).replace("PERSONAL", "ENTERPRISE"), "admin"), 422, "VALIDATION_FAILED"); assertThat(fixture.allFacts()).isEqualTo(before);
        for (long value : List.of(9007199254740993L, Long.MAX_VALUE)) { var response = fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, number++, true).replace("\"priceCents\":0", "\"priceCents\":" + value), "admin"); assertThat(fixture.success(response, 201).get("priceCents").bigIntegerValue().longValueExact()).isEqualTo(value); fixture.exactStored(response); }
    }
    @Test void emptyBenefitsAndChannelsRemainValidAndStable() throws Exception { UUID product = fixture.product(); var created = fixture.create(product, 1, false); var body = fixture.success(created, 201); UUID version = UUID.fromString(body.get("catalogVersionId").asString()); assertThat(body.get("benefitLines").size()).isZero(); assertThat(body.get("channels").size()).isZero(); fixture.exactStored(created); fixture.exactStored(fixture.replace(version, 1, 2)); assertThat(fixture.value("SELECT count(*) FROM catalog_order.catalog_offer")).isEqualTo("0"); }
    @Test void canonicalOrderingIgnoresRequestAndPhysicalRowOrder() throws Exception { UUID product = fixture.product(); var created = fixture.create(product, 1, true); fixture.success(created, 201); var replay = fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, 1, true).replace("[\"WEB\",\"MINIAPP\"]", "[\"MINIAPP\",\"WEB\"]"), "admin"); fixture.success(replay, 200); assertThat(replay.body()).isEqualTo(created.body()); fixture.exactStored(created); assertThat(fixture.mapper.readTree(created.body()).get("benefitLines").get(0).get("entitlementType").asString()).isEqualTo("AI_SECONDS"); }
    @Test void replaceUpdatesCommercialSnapshotAndRevisionExactlyOnce() throws Exception { UUID version = fixture.draft(true);
        String beforeAudit = fixture.value("SELECT jsonb_build_object('productId',product_id,'versionNo',version_no,'saleStatus',sale_status,'revision',revision,'snapshotSha256',snapshot_sha256)::text FROM catalog_order.catalog_version WHERE id=?", version);
        var response = fixture.replace(version, 1, 9); assertThat(fixture.success(response, 200).get("revision").asInt()).isEqualTo(2); fixture.exactStored(response); assertThat(fixture.base.audits()).isEqualTo(2);
        assertThat(fixture.value("SELECT before_snapshot=?::jsonb FROM audit.audit_fact WHERE action_code='CATALOG_DRAFT_REPLACE'", beforeAudit)).isEqualTo("t");
        assertThat(fixture.value("SELECT a.after_snapshot=jsonb_build_object('productId',v.product_id,'versionNo',v.version_no,'saleStatus',v.sale_status,'revision',v.revision,'snapshotSha256',v.snapshot_sha256) AND a.reason_code='ACTION_DERIVED' AND a.actor_type='EMPLOYEE' AND a.actor_id=? AND a.object_type='CATALOG_VERSION' AND a.trace_id=? FROM audit.audit_fact a JOIN catalog_order.catalog_version v ON a.object_id=v.id WHERE a.action_code='CATALOG_DRAFT_REPLACE'", fixture.base.shared.employee, fixture.callerTrace().toString())).isEqualTo("t"); assertThat(fixture.value("SELECT count(*) FROM audit.audit_fact WHERE action_code='CATALOG_DRAFT_REPLACE' AND request_id=?", "catalog_version:" + version + ":draft:replace:2")).isEqualTo("1"); fixture.mutate("UPDATE catalog_order.catalog_version SET snapshot=jsonb_set(snapshot,'{priceCents}','\"9\"') WHERE id=?", version); String before = fixture.allFacts(); for (int revision : List.of(1, 2)) fixture.problem(fixture.replace(version, revision, 9), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void replaceRegeneratesTokensWithoutChangingOfferIdentityOrChannelSet() throws Exception { UUID version = fixture.draft(true); String immutable = fixture.immutable(version); String tokens = fixture.value("SELECT string_agg(version_token,',' ORDER BY channel) FROM catalog_order.catalog_offer"); var replaced = fixture.replace(version, 1, 1); String hash = fixture.success(replaced, 200).get("snapshotSha256").asString(); assertThat(fixture.immutable(version)).isEqualTo(immutable); assertThat(fixture.value("SELECT string_agg(version_token,',' ORDER BY channel) FROM catalog_order.catalog_offer")).isNotEqualTo(tokens); for (String channel : List.of("MINIAPP", "WEB")) assertThat(fixture.value("SELECT version_token FROM catalog_order.catalog_offer WHERE catalog_version_id=? AND channel=?", version, channel)).isEqualTo(OperationsCatalogDraftFixture.hash("catalog-draft-token:v1\n" + version + "\n" + channel + "\n2\n" + hash)); assertThat(fixture.value("SELECT min(revision)||':'||max(revision) FROM catalog_order.catalog_offer")).isEqualTo("2:2"); }
    @Test void benefitRowsAndProductVersionCreatorTimestampsRemainUnchanged() throws Exception { UUID version = fixture.draft(true); String before = fixture.immutable(version); fixture.success(fixture.replace(version, 1, 1), 200); fixture.success(fixture.replace(version, 2, 2), 200); assertThat(fixture.immutable(version)).isEqualTo(before); fixture.noPlatformWrites(); }
    @Test void appliedReplaceRetryReplaysWithoutAnyWrites() throws Exception { UUID version = fixture.draft(true); var replaced = fixture.replace(version, 1, 2); fixture.success(replaced, 200); String before = fixture.allFacts(); var replay = fixture.replace(version, 1, 2); fixture.success(replay, 200); assertThat(replay.body()).isEqualTo(replaced.body()); assertThat(fixture.allFacts()).isEqualTo(before); fixture.mutate("UPDATE catalog_order.catalog_version SET snapshot='{}'::jsonb WHERE id=?", version); before = fixture.allFacts(); for (int revision : List.of(1, 2)) fixture.problem(fixture.replace(version, revision, 2), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void staleFutureAndNonSuccessorViewsReturnExact409() throws Exception { UUID version = fixture.draft(true); fixture.success(fixture.replace(version, 1, 1), 200); fixture.success(fixture.replace(version, 2, 2), 200); String before = fixture.allFacts(); for (int revision : List.of(1, 4, Integer.MAX_VALUE)) fixture.problem(fixture.replace(version, revision, 2), 409, "CATALOG_DRAFT_STALE_VIEW"); fixture.problem(fixture.replace(version, 2, 7), 409, "CATALOG_DRAFT_STALE_VIEW"); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void nonDraftReplaceConflictsBeforeRevisionReplay() throws Exception { UUID version = fixture.draft(true); fixture.base.success(fixture.base.request(version, true, null, 1)); String before = fixture.allFacts(); for (int revision : List.of(1, 2, Integer.MAX_VALUE)) fixture.problem(fixture.replace(version, revision, 0), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.allFacts()).isEqualTo(before); }
    void createRace(boolean changed) throws Exception {
        for (boolean expire : List.of(false, true)) {
            fixture.reset(); UUID product = fixture.product(); String body = fixture.createBody(product, 1, true); String contender = changed ? body.replace("\"priceCents\":0", "\"priceCents\":1") : body;
            var race = fixture.race(() -> fixture.create(product, 1, true), () -> fixture.request("POST", OperationsCatalogDraftFixture.BASE, contender, "admin"), expire, false);
            fixture.success(race.winner(), 201);
            if (changed || race.expired()) fixture.problem(race.contender(), 409, "CATALOG_DRAFT_CONFLICT"); else { fixture.success(race.contender(), 200); assertThat(race.contender().body()).isEqualTo(race.winner().body()); }
            assertThat(fixture.base.audits()).isEqualTo(1); String before = fixture.allFacts(); fixture.success(fixture.create(product, 1, true), 200); assertThat(fixture.allFacts()).isEqualTo(before); fixture.noPlatformWrites();
        }
    }
    @Test void concurrentIdenticalCreatesReplayOrTimeOutWithoutDuplicateFacts() throws Exception { createRace(false); fixture.reset(); UUID product = fixture.product(); var race = fixture.race(() -> fixture.create(product, 1, true), () -> fixture.create(product, 1, true), true, true); fixture.problem(race.winner(), 500, "INTERNAL"); assertThat(fixture.base.audits()).isZero(); fixture.success(fixture.create(product, 1, true), 201); assertThat(fixture.base.audits()).isEqualTo(1); }
    @Test void concurrentChangedCreatesConflictWithoutDuplicateFacts() throws Exception { createRace(true); }
    void replaceRace(boolean changed) throws Exception { for (boolean expire : List.of(false, true)) { fixture.reset(); UUID version = fixture.draft(true); String immutable = fixture.immutable(version); var race = fixture.race(() -> fixture.replace(version, 1, 1), () -> fixture.replace(version, 1, changed ? 2 : 1), expire, false); fixture.success(race.winner(), 200); if (race.expired()) fixture.problem(race.contender(), 409, "CATALOG_DRAFT_CONFLICT"); else if (changed) fixture.problem(race.contender(), 409, "CATALOG_DRAFT_STALE_VIEW"); else fixture.success(race.contender(), 200); assertThat(fixture.base.audits()).isEqualTo(2); String before = fixture.allFacts(); fixture.success(fixture.replace(version, 1, 1), 200); assertThat(fixture.allFacts()).isEqualTo(before); assertThat(fixture.immutable(version)).isEqualTo(immutable); fixture.noPlatformWrites(); } }
    @Test void concurrentEqualReplacesReplayOrTimeOutAfterOneApplication() throws Exception { replaceRace(false); }
    @Test void concurrentDifferentReplacesReturnStaleOrLockConflictAfterOneApplication() throws Exception { replaceRace(true); }
    @Test void draftReplaceAndPublicationShareProductLockAndCoherentSnapshot() throws Exception {
        UUID version = fixture.draft(true); UUID firstVersion = version; var race = fixture.race(() -> fixture.replace(firstVersion, 1, 8), () -> fixture.base.request(firstVersion, true, null, 2), false, false); fixture.success(race.winner(), 200);
        if (race.contender().statusCode() == 409) fixture.base.success(fixture.base.request(version, true, null, 2)); else fixture.base.success(race.contender());
        String hash = fixture.value("SELECT snapshot_sha256 FROM catalog_order.catalog_version WHERE id=?", version); assertThat(fixture.value("SELECT payload_redacted->>'snapshotSha256' FROM platform.outbox_event WHERE event_type='CATALOG_VERSION_PUBLISHED'")).isEqualTo(hash);
        fixture.reset(); version = fixture.draft(true); UUID target = version;
        var reverse = fixture.race(() -> fixture.base.request(target, true, null, 1), () -> fixture.replace(target, 1, 8), false, false); fixture.base.success(reverse.winner()); fixture.problem(reverse.contender(), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.value("SELECT price_cents FROM catalog_order.catalog_version WHERE id=?", target)).isEqualTo("0");
    }
    @Test void zeroRowAndRawUniqueRacesRollbackBeforeBoundedRecovery() throws Exception { UUID product = fixture.product(); for (String state : List.of("RAW_23505", "RAW_40001")) { fixture.entries.clear(); fixture.fail(state); fixture.problem(fixture.create(product, 1, true), 409, "CATALOG_DRAFT_CONFLICT"); assertThat(fixture.calls("FROM operations_iam.employee_account")).hasSize(2); assertThat(fixture.base.audits()).isZero(); } UUID version = UUID.fromString(fixture.success(fixture.create(product, 1, true), 201).get("catalogVersionId").asString()); String before = fixture.allFacts(); fixture.entries.clear(); fixture.started.clear(); fixture.fail("ZERO_UPDATE"); fixture.problem(fixture.replace(version, 1, 5), 503, "SERVICE_UNAVAILABLE"); assertThat(fixture.allFacts()).isEqualTo(before);
        assertThat(fixture.calls("WHERE id = ? FOR UPDATE")).hasSize(2);
        assertThat(fixture.started.stream().filter(sql -> sql.startsWith("UPDATE catalog_order.catalog_version"))).hasSize(1);
        assertThat(fixture.calls("UPDATE catalog_order.catalog_offer")).isEmpty(); assertThat(fixture.calls("audit.append_fact")).isEmpty();
        fixture.fail("RAW_40001"); fixture.problem(fixture.replace(version, 1, 5), 503, "SERVICE_UNAVAILABLE"); fixture.success(fixture.replace(version, 1, 5), 200); before = fixture.allFacts(); fixture.entries.clear(); fixture.fail("RAW_40001"); fixture.success(fixture.replace(version, 1, 5), 200); assertThat(fixture.calls("FROM operations_iam.employee_account")).hasSize(2); assertThat(fixture.allFacts()).isEqualTo(before); }
    @Test void auditAndChildFailuresRollbackAllOwnerFacts() throws Exception { UUID product = fixture.product(); for (String stage : List.of("VERSION", "BENEFIT", "OFFER", "AUDIT", "RESTORE")) { String before = fixture.allFacts(); fixture.fail(stage); fixture.problem(fixture.create(product, 1, true), stage.equals("RESTORE") ? 503 : 500, stage.equals("RESTORE") ? "SERVICE_UNAVAILABLE" : "INTERNAL"); assertThat(fixture.allFacts()).isEqualTo(before); } UUID version = UUID.fromString(fixture.success(fixture.create(product, 1, true), 201).get("catalogVersionId").asString()); for (String stage : List.of("UPDATE", "TOKEN", "AUDIT", "RESTORE")) { String before = fixture.allFacts(); fixture.fail(stage); fixture.problem(fixture.replace(version, 1, 9), stage.equals("RESTORE") ? 503 : 500, stage.equals("RESTORE") ? "SERVICE_UNAVAILABLE" : "INTERNAL"); assertThat(fixture.allFacts()).isEqualTo(before); } }
    @Test void replaysConflictsAndDenialsHaveNoAuditOutboxOrIdempotencyWrites() throws Exception { UUID product = fixture.product(); fixture.success(fixture.create(product, 1, true), 201); String before = fixture.allFacts(); fixture.success(fixture.create(product, 1, true), 200); for (String token : List.of("ops", "disabled", "missing")) fixture.problem(fixture.request("POST", OperationsCatalogDraftFixture.BASE, fixture.createBody(product, 1, true), token), token.equals("missing") ? 503 : 403, token.equals("missing") ? "SERVICE_UNAVAILABLE" : "FORBIDDEN"); assertThat(fixture.allFacts()).isEqualTo(before); fixture.noPlatformWrites(); }
    @Test void fullHttpResponsesHaveExactBytesHeadersLengthsAndNoPrivateFacts() throws Exception { UUID product = fixture.product(); var first = fixture.create(product, 1, true); UUID version = UUID.fromString(fixture.success(first, 201).get("catalogVersionId").asString()); fixture.exactStored(first); var replay = fixture.create(product, 1, true); fixture.success(replay, 200); assertThat(replay.body()).isEqualTo(first.body()); var replaced = fixture.replace(version, 1, Long.MAX_VALUE); fixture.success(replaced, 200); fixture.exactStored(replaced); assertThat(fixture.replace(version, 1, Long.MAX_VALUE).body()).isEqualTo(replaced.body());
        for (String state : List.of("missing", "stale", "published")) { if (state.equals("published")) fixture.base.success(fixture.base.request(version, true, null, 2)); UUID target = state.equals("missing") ? UUID.randomUUID() : version; String before = fixture.allFacts(); fixture.entries.clear(); for (String field : List.of("productId", "versionNo", "benefitLines", "channels", "saleStatus", "status", "createdAt", "publishedAt", "versionToken", "createdByEmployeeId", "snapshot", "snapshotSha256", "revision", "versionId", "catalogVersionId", "unknown")) for (String value : List.of("null", "1", "[]", "\"DRAFT\"")) fixture.problem(fixture.request("PUT", OperationsCatalogDraftFixture.BASE + "/" + target + "/draft", "{\"" + field + "\":" + value + "," + fixture.replaceBody(1, Long.MAX_VALUE).substring(1), "admin"), 422, "VALIDATION_FAILED"); assertThat(fixture.calls("FROM operations_iam.employee_account")).isEmpty(); assertThat(fixture.allFacts()).isEqualTo(before); }
    }
}
